'use strict';
function evaluationPage(){const e=W().evaluation;return sHead('sEvaluation','S31 · J16-A01–A05')+sPolicy('D-013/D-004',q('Review-before-publication is illustrated, not selected policy. No metric scale is invented.','المراجعة قبل النشر مثال وليست سياسة معتمدة. لا يُبتكر مقياس للتقييم.'))+`<div class="form-panel">${errorBox()}<div class="work-card">${property(q('Player / sport / schema','اللاعب / الرياضة / المعيار'),'Demo Player · Demo sport · narrative-v1')}${property(t('status'),badge(q(e.state,({draft:'مسودة',submitted:'مقدم',returned:'معاد للتعديل',approved:'معتمد',published:'منشور'})[e.state])))}${sField('eval-text','Publishable feedback','ملاحظات قابلة للنشر',e.text)}${sField('eval-private','Private staff note · never family-visible','ملاحظة داخلية لا تظهر للعائلة',e.privateNote)}${sField('eval-reason','Review / revision reason','سبب المراجعة أو التعديل',e.reason)}</div>${sButtons(btn(q('Save draft','حفظ المسودة'),'s-eval-save'),btn(q('Submit for illustrative review','التقديم للمراجعة التوضيحية'),'s-eval-submit','primary'),btn(q('Return for changes','إعادة للتعديل'),'s-eval-return'),btn(q('Approve review','اعتماد المراجعة'),'s-eval-approve'))}<div class="section work-card"><h3>${q('Publication preview','معاينة النشر')}</h3><p class="subtitle">${esc(e.text||q('No feedback saved','لا توجد ملاحظات محفوظة'))}</p><p class="draft-note">${q('Audience: currently verified guardian / policy-eligible player only. Internal note excluded.','الجمهور: ولي الأمر المتحقق منه أو اللاعب المؤهل بالسياسة فقط. الملاحظة الداخلية مستبعدة.')}</p>${sConfirm('eval-publish')}${sButtons(btn(q('Publish snapshot','نشر نسخة ثابتة'),'s-eval-publish','primary'),btn(q('View family projection','عرض العائلة'),'nav:sProgress'))}</div>${sButtons(btn(q('Start successor revision','بدء تعديل لاحق'),'s-eval-revise'),btn(q('Withdraw current publication','سحب النشر الحالي'),'s-eval-withdraw','danger'))}</div>`}
function progressPage(){const e=W().evaluation,p=e.publications.filter(p=>!p.withdrawn).at(-1);return sHead('sProgress','S32/S47 · J16-A06')+`<div class="form-panel">${p?`<div class="work-card"><h2>${q('Published goals and feedback','أهداف وملاحظات منشورة')}</h2><p class="subtitle">${esc(p.text)}</p><p class="draft-note"><bdi dir="ltr">Publication ${p.version} · narrative-v1</bdi></p></div>`:notice(q('No published evaluation','لا يوجد تقييم منشور'),q('Drafts, returned versions and private notes are not projected. Missing is not a zero score.','لا تظهر المسودات أو النسخ المعادة أو الملاحظات الخاصة. الغياب لا يعني درجة صفر.'))}${sButtons(btn(q('Return to author/reviewer fixture','العودة إلى نموذج الكاتب والمراجع'),'nav:sEvaluation'))}</div>`}
function financePage(){const f=W().finance;return sHead('sFinance','S36–S41 · J17/J18')+sPolicy('D-001/D-005/D-006/D-007/D-010',q('Enter fictional integer demonstration units; no currency, price, fee, tax or proration is selected. Guardian relationship does not grant payer authority.','أدخل وحدات تجريبية صحيحة خيالية؛ لا تُختار عملة أو سعر أو رسوم أو ضريبة أو توزيع نسبي. علاقة الولي لا تمنح سلطة الدفع.'))+`<div class="form-panel">${errorBox()}<div class="work-card">${property(q('Payer authority','سلطة الدافع'),q('Separate authorized-payer fixture','نموذج دافع مصرح به منفصل'))}${property(q('Plan/version','الخطة والإصدار'),q('Policy to confirm · no calculation formula','سياسة للتأكيد · لا صيغة حساب'))}${sField('bill-units','Fictional bill units · integer','وحدات فاتورة خيالية صحيحة','', 'number')}${sConfirm('bill-review')}${sButtons(btn(q('Issue reviewed demonstration bill','إصدار الفاتورة التجريبية المراجعة'),'s-bill','primary'))}</div>${f.bill?`<div class="work-card section">${property(q('Issued bill','فاتورة صادرة'),'<bdi>SIM-BILL-1 · '+f.bill.units+' demo units</bdi>')}${property(q('Settled / outstanding','المسدد / المتبقي'),`${f.receipt?f.receipt.allocated:0} / ${f.bill.units-(f.receipt?.allocated||0)} ${q('demo units','وحدة تجريبية')}`)}${f.unknown?notice(t('unknown'),q('Receipt may be committed. Reconcile SIM-RECEIPT-1 before a replacement.','قد يكون الإيصال محفوظاً. سوِّ SIM-RECEIPT-1 قبل البديل.'),'warn')+btn(t('check'),'s-receipt-check','primary'):f.receipt?notice(q('Confirmed local receipt','إيصال محلي مؤكد'),`<bdi>SIM-RECEIPT-1 · ${f.receipt.units}</bdi>`,'success'):`${sField('receipt-units','Received fictional units','وحدات مستلمة خيالية','','number')}${sField('allocation-units','Allocation to this bill','التخصيص لهذه الفاتورة','','number')}${sField('payment-ref','Fictional external reference','مرجع خارجي خيالي')}${sConfirm('receipt-review')}${sButtons(btn(q('Record receipt + allocation','تسجيل الإيصال والتخصيص'),'s-receipt','primary'),btn(q('Lost response after local commit','فقدان الرد بعد الحفظ المحلي'),'s-receipt-unknown'))}`}</div>`:''}${f.receipt&&!f.unknown?`<div class="section work-card"><h3>${q('Correction / refund review','مراجعة التصحيح والاسترداد')}</h3>${sField('refund-reason','Reason and original receipt reference','السبب ومرجع الإيصال الأصلي')}${sButtons(btn(q('Request reviewed correction','طلب تصحيح بمراجعة'),'s-adjust'),btn(q('Request external refund · pending','طلب استرداد خارجي · معلّق'),'s-refund'))}${property(q('Reconciliation','التسوية'),f.adjustments.length?f.adjustments.map(a=>esc(a)).join('<br>'):q('No correction or external refund confirmed','لم يُؤكد تصحيح أو استرداد خارجي'))}</div>`:''}</div>`}
function payPage(){const p=W().pay;return sHead('sPay','S42–S44 · J19')+sPolicy('D-008/D-007',q('Contract basis, rates, rounding and approvers await policy. Amounts remain unavailable; no guessed earnings.','أساس العقد والأسعار والتقريب والمعتمدون بانتظار السياسة. المبالغ غير متاحة؛ لا مستحقات تخمينية.'))+`<div class="form-panel">${errorBox()}<div class="work-card">${property(q('Effective contract','العقد الساري'),p.contract?'Demo-contract-v1 · 2026-11':q('Missing · exception','مفقود · استثناء'))}${property(q('Calculation lines','بنود الحساب'),q('Session SES1 · source version1 · rate unavailable','الحصة SES1 · إصدار المصدر١ · السعر غير متاح'))}${property(t('status'),esc(stateLabel(p.state)))}${property(q('Earned / approved / paid','المكتسب / المعتمد / المدفوع'),q('Amounts unavailable pending approved formula','المبالغ غير متاحة حتى اعتماد الصيغة'))}${sField('pay-reason','Contract/exception review reason','سبب مراجعة العقد والاستثناء')}${sButtons(btn(q('Attach effective contract fixture','ربط نموذج عقد سارٍ'),'s-pay-contract'),btn(q('Resolve exception for design review','حل الاستثناء لمراجعة التصميم'),'s-pay-resolve'),btn(q('Prepare review run','إعداد دورة للمراجعة'),'s-pay-prepare','primary'),btn(q('Approve illustrative run','اعتماد الدورة التوضيحية'),'s-pay-approve'))}</div><div class="section work-card"><h3>${q('Trainer own statement','كشف المدرب الشخصي')}</h3><p class="subtitle">${q('Own source lines only; no colleague rates or management notes. Approval is not a payout.','بنود مصادره فقط؛ دون أسعار الزملاء أو الملاحظات الإدارية. الاعتماد لا يعني الدفع.')}</p>${property(q('Statement status','حالة الكشف'),esc(stateLabel(p.state)))}${sField('payout-ref','Fictional payout reference','مرجع صرف خيالي',p.reference)}${sButtons(btn(q('Record payout intent · not money movement','تسجيل نية صرف دون حركة مالية'),'s-pay-payout'))}</div></div>`}
function commercePage(){const c=W().commerce;return sHead('sCommerce','S08/S09/S45 · J20')+sPolicy('D-009/D-010',q('No prices, limits, trial, grace period or restriction allowances are selected.','لم تُختَر أسعار أو حدود أو تجربة أو مهلة أو استثناءات تقييد.'))+`<div class="form-panel">${errorBox()}<div class="work-card">${property(q('Current plan / version','الخطة الحالية وإصدارها'),'Demo-plan-v1 · '+q('terms unconfirmed','الشروط غير مؤكدة'))}${property(q('Requested plan','الخطة المطلوبة'),'Demo-plan-v2 · '+q('not a sales offer','ليست عرضاً تجارياً'))}${property(t('status'),esc(stateLabel(c.state)))}${property(q('Change consequences','نتائج التغيير'),q('Preserve history. Preview impacted capabilities; exact limits/allowed recovery depend on D-009. No auto-deletion.','حفظ التاريخ. معاينة الوظائف المتأثرة؛ الحدود والتعافي تتبع D-009. لا حذف آلي.'))}${sConfirm('plan-review')}${sButtons(btn(q('Schedule illustrative change','جدولة تغيير توضيحي'),'s-plan-schedule','primary'),btn(q('Advance to effective fixture','تقديم الحالة إلى السريان'),'s-plan-effective'),btn(q('Inspect restricted-state example','فحص مثال التقييد'),'s-plan-restrict'))}</div><div class="section work-card"><h3>${q('Platform invoice / private proof review','فاتورة المنصة ومراجعة الإثبات الخاص')}</h3><p class="subtitle">${q('Separate from family collections. No file upload or payment occurs.','منفصلة عن تحصيل العائلات. لا رفع ملف أو دفع.')}</p>${property(q('Proof claim','طلب الإثبات'),esc(stateLabel(c.proof)))}${sField('proof-reason','Review reason','سبب المراجعة')}${sButtons(btn(q('Stage fictional proof','تهيئة إثبات خيالي'),'s-proof-stage'),btn(q('Submit verified-file fixture','إرسال نموذج ملف متحقق منه'),'s-proof-submit'),btn(q('Reject with reason','رفض بسبب'),'s-proof-reject'),btn(q('Accept illustrative review','قبول المراجعة التوضيحية'),'s-proof-accept'))}${sButtons(btn(q('Review recovery after resolution','مراجعة التعافي بعد الحل'),'s-plan-recover'))}</div></div>`}
function commercialAction(k,v){const e=W().evaluation,f=W().finance,p=W().pay,c=W().commerce;if(k.startsWith('s-eval-')){const verb=k.slice(7);if(['save','submit'].includes(verb)){if(!sValue('eval-text')){sError();return true}if(e.state==='published'){sError(q('Start a successor revision first.','ابدأ تعديلاً لاحقاً أولاً.'));return true}e.text=sValue('eval-text');e.privateNote=sValue('eval-private');e.reason=sValue('eval-reason');e.state=verb==='submit'?'submitted':'draft'}else if(verb==='return'){if(e.state!=='submitted'||!sValue('eval-reason')){sError();return true}e.state='returned';e.reason=sValue('eval-reason')}else if(verb==='approve'){if(e.state!=='submitted'){sError();return true}e.state='approved'}else if(verb==='publish'){if(e.state!=='approved'||!sCheck('eval-publish')){sError();return true}e.publications.push({text:e.text,version:e.version,withdrawn:false});e.state='published'}else if(verb==='revise'){if(!e.publications.length||!sValue('eval-reason')){sError();return true}e.version++;e.state='draft';e.reason=sValue('eval-reason')}else if(verb==='withdraw'){const pub=e.publications.at(-1);if(!pub||!sValue('eval-reason')){sError();return true}pub.withdrawn=true;e.state='draft'}sSaved(q('Evaluation transition','انتقال التقييم'));return true}
if(k==='s-bill'){const units=+sValue('bill-units');if(f.bill||!Number.isSafeInteger(units)||units<=0||!sCheck('bill-review'))sError();else{f.bill={units};sSaved(q('Bill issued','صدرت الفاتورة'))}return true}
if(['s-receipt','s-receipt-unknown'].includes(k)){const units=+sValue('receipt-units'),allocated=+sValue('allocation-units');if(!f.bill||f.receipt||!Number.isSafeInteger(units)||!Number.isSafeInteger(allocated)||units<=0||allocated<0||allocated>units||allocated>f.bill.units||!sValue('payment-ref')||!sCheck('receipt-review'))sError();else{f.receipt={units,allocated,ref:'SIM-RECEIPT-1',unapplied:units-allocated};f.unknown=k.endsWith('unknown');sSaved(q('Receipt and allocation','الإيصال والتخصيص'))}return true}if(k==='s-receipt-check'){f.unknown=false;sSaved(q('Original receipt reconciled','تسوية الإيصال الأصلي'));return true}if(k==='s-adjust'||k==='s-refund'){if(!f.receipt||f.unknown||!sValue('refund-reason'))sError();else{f.adjustments.push(q(k==='s-refund'?'Refund requested · external outcome pending':'Correction requested · approver policy pending',k==='s-refund'?'طلب استرداد · النتيجة الخارجية معلّقة':'طلب تصحيح · سياسة المعتمد معلّقة'));sSaved(q('Request only; original receipt preserved','طلب فقط؛ الإيصال الأصلي محفوظ'))}return true}
if(k.startsWith('s-pay-')){if(k==='s-pay-contract'){p.contract=true}else if(k==='s-pay-resolve'){if(!p.contract||!sValue('pay-reason')){sError();return true}p.exception=false}else if(k==='s-pay-prepare'){if(p.exception||!p.contract){sError(q('Resolve the effective-contract exception first.','حل استثناء العقد الساري أولاً.'));return true}p.state='review-required'}else if(k==='s-pay-approve'){if(p.state!=='review-required'){sError();return true}p.state='approved · amounts policy pending'}else if(k==='s-pay-payout'){if(!p.state.startsWith('approved')||!sValue('payout-ref')){sError();return true}p.reference=sValue('payout-ref');p.state='payout recorded as intent only · amount unconfirmed'}sSaved(q('Compensation fixture transition','انتقال نموذج المستحقات'));return true}
if(k.startsWith('s-plan-')){if(k==='s-plan-schedule'){if(!sCheck('plan-review')){sError();return true}c.state='scheduled'}else if(k==='s-plan-effective'){if(c.state!=='scheduled'){sError();return true}c.state='effective fixture'}else if(k==='s-plan-restrict')c.state='restricted example · exact allowances policy pending';else if(k==='s-plan-recover'){if(c.proof!=='accepted fixture'){sError(q('Resolve the illustrative claim first; actual recovery rules need policy.','حل الطلب التوضيحي أولاً؛ قواعد التعافي الفعلية تحتاج سياسة.'));return true}c.state='recovery reviewed · no commercial activation'}sSaved(q('Plan fixture transition','انتقال نموذج الخطة'));return true}
if(k.startsWith('s-proof-')){if(k==='s-proof-stage')c.proof='staged';else if(k==='s-proof-submit'){if(!['staged','rejected'].includes(c.proof)){sError();return true}c.proof='under review'}else{if(c.proof!=='under review'||!sValue('proof-reason')){sError();return true}c.proof=k==='s-proof-accept'?'accepted fixture':'rejected'}sSaved(q('Proof-review fixture','نموذج مراجعة الإثبات'));return true}return false}
